Demonstrate discriminated union exhaustiveness checking with never:
type Action = { type: 'open'; id: string } | { type: 'close'; id: string };
function handle(action: Action): void {
    switch (action.type) {
        case 'open': return;
        case 'close': return;
        default: {
            const _exhaustive: never = action;
            throw new Error(`Unhandled action: ${_exhaustive}`);
        }
    }
}
Result: Adding a third action type without updating handle triggers a compile-time exhaustiveness error.

Demonstrate concurrent state scheduling using useTransition:
import { useState, useTransition } from 'react';
function FilterableList({ items }: { items: string[] }) {
    const [query, setQuery] = useState('');
    const [filtered, setFiltered] = useState(items);
    const [isPending, startTransition] = useTransition();
    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setQuery(e.target.value); // Urgent input update
        startTransition(() => {
            setFiltered(items.filter(item => item.includes(e.target.value))); // Non-urgent filter update
        });
    };
    return <input value={query} onChange={handleChange} />;
}
Result: Typing remains responsive at 60fps because filtering work yields to urgent keystroke updates.

Demonstrate streaming token consumption with AbortController:
async function streamAIResponse(url: string, signal: AbortSignal, onChunk: (text: string) => void) {
    const response = await fetch(url, { signal });
    if (!response.ok || !response.body) throw new Error(`HTTP error: ${response.status}`);
    const reader = response.body.getReader();
    const decoder = new TextDecoder('utf-8');
    while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        onChunk(decoder.decode(value, { stream: true }));
    }
}
Result: Text chunks render incrementally as received, and triggering signal abort halts the stream immediately.

Demonstrate secure postMessage receiver validation:
window.addEventListener('message', (event: MessageEvent) => {
    if (event.origin !== 'https://trusted-auth.example.com') return; // Strict origin filter
    if (!event.data || event.data.type !== 'AUTH_SUCCESS') return;
    console.log('Received valid auth token:', event.data.token);
});
Result: Unsolicited messages from malicious or unauthorized third-party origins are ignored without processing.

Demonstrate dynamic code splitting with React.lazy and Suspense:
import React, { Suspense, lazy } from 'react';
const HeavyAnalyticsChart = lazy(() => import('./HeavyAnalyticsChart'));
function Dashboard() {
    return (
        <Suspense fallback={<div>Loading chart component...</div>}>
            <HeavyAnalyticsChart />
        </Suspense>
    );
}
Result: Heavy charting libraries are omitted from the main bundle and downloaded on demand when the component mounts.

Demonstrate safe HTML sanitization with DOMPurify before DOM insertion:
import DOMPurify from 'dompurify';
function renderSafeHTML(untrustedMarkup: string): string {
    return DOMPurify.sanitize(untrustedMarkup, {
        ALLOWED_TAGS: ['b', 'i', 'em', 'strong', 'a', 'p'],
        ALLOWED_ATTR: ['href', 'target', 'rel']
    });
}
const safe = renderSafeHTML('<img src=x onerror=alert(1)><b>Welcome</b>');
Result: Malicious script payloads and dangerous onerror event attributes are stripped, leaving only '<b>Welcome</b>'.
